def semver_sort(versions):
    def parse_version(version):
        # Split by + to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by - to separate version from pre-release
        if '-' in version_without_build:
            version_part, prerelease_part = version_without_build.split('-', 1)
        else:
            version_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(prerelease_identifiers):
        # A version with no pre-release sorts after one with pre-release
        # So we need to return a tuple that sorts correctly
        if prerelease_identifiers is None:
            # No pre-release: sorts after any pre-release
            return (1,)  # Higher than (0, ...)
        else:
            # Has pre-release: sorts before non-prerelease
            # Convert identifiers to comparable form
            converted = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    # All-digit: compare numerically, sorts before non-digit
                    converted.append((0, int(identifier)))
                else:
                    # Non-digit: compare by ASCII order, sorts after digit
                    converted.append((1, identifier))
            return (0, tuple(converted))

    def sort_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_identifiers))

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

